"use strict";

/**
 * The gate. Do not edit this file: what changes from one tool to the next is written in tool.json and
 * confirmed.json, and what changes from one system to the next is in connect.js.
 *
 * It does three things, none of them specific to a tool:
 *
 *   read the declarations   the labelled lines of the tool's description ([Required], [Verify],
 *                           [Notice]), the confirmed form of each line (confirmed.json), the formats
 *                           and sources in the input schema, and the user's checklist items
 *   run the declared checks every check is a JSON Schema, run by a standard validator (Ajv). A
 *                           schema it cannot run leaves the check unverified, never passed
 *   run the flow            a LangGraph graph: gate → ask → gate … → execute. The gate is the
 *                           unchanged skeleton (execution-state-preflight.js): it judges once from
 *                           what has been collected and returns. Asking, waiting and resuming are
 *                           the graph's.
 *
 * The model is asked where the user's words are (and what they call the act, and when). It is never
 * asked whether a check passed. Each location it gives is checked against the user's own text.
 *
 * provider-checklist-example/ runs this file against hooks-example/ (v1) on the same inputs and
 * holds its tests.
 */

const { StateGraph, Annotation, interrupt, Command, MemorySaver, START, END } = require("@langchain/langgraph");

// The skeleton: one file, copied beside this folder (the repository layout) or into it.
const { createPreflight } = (() => {
  try { return require("./execution-state-preflight"); }
  catch (e) { if (e.code !== "MODULE_NOT_FOUND") throw e; return require("../execution-state-preflight"); }
})();

const Ajv = require("ajv");
const addFormats = require("ajv-formats");

// The validator. strict: a keyword it does not know is an error, not something to skip — a declared
//   check that cannot be run must not read as a check that passed. The two x- keywords are the
//   schema's own declarations about sources, not checks on the value, so they are registered as
//   annotations and ignored here.
const ajv = new Ajv({ strict: true, allErrors: true });
addFormats(ajv);
ajv.addVocabulary(["x-allowed-sources", "x-settled-at-execution"]);
const compiled = new WeakMap();

// { ok: true|false, errors } when the value was checked; { error } when the schema cannot be compiled.
function checkAgainst(schema, value) {
  if (!schema || typeof schema !== "object") return { error: "no schema" };
  let validate = compiled.get(schema);
  if (!validate) {
    try { validate = ajv.compile(schema); } catch (e) { return { error: e.message }; }
    compiled.set(schema, validate);
  }
  const ok = validate(value);
  return { ok, errors: ok ? null : ajv.errorsText(validate.errors) };
}

const WHEN_CASES = ["immediate", "scheduled", "conditional", "recurring"];

function squash(s) {
  return String(s).toLowerCase().replace(/[.,!?;:'"()]/g, " ").replace(/\s+/g, " ").trim();
}

// Where a quoted value sits in a segment's text: the first exact occurrence, else the first that
//   differs only in case. null when it is not there.
function locateQuote(text, quote) {
  if (typeof text !== "string" || typeof quote !== "string" || quote === "") return null;
  let at = text.indexOf(quote);
  if (at < 0) {
    const lower = text.toLowerCase().indexOf(quote.toLowerCase());
    if (lower >= 0) at = lower;
  }
  return at >= 0 ? [at, at + quote.length] : null;
}

function trustedText(instruction) {
  return (instruction ?? []).filter(s => s?.trust === "user").map(s => s.text).join("\n");
}

// ── The provider's declaration ──────────────────────────────────────────────────────────────────
// A labelled line is a line of the description that starts with a bracketed word. Matching, not
//   interpretation: the bracketed word goes to the skeleton as the label, and the skeleton routes a
//   word it does not know to definition_repair. So "[Requried]" is not dropped as prose — a typo in a
//   declaration does not delete the condition.
//   NOTE: a prose line that happens to start with brackets ("[Beta] …") is read as a label too, and
//     held for definition repair. That is the fail-closed reading, and the provider can reword it.
const LABEL_LINE = /^\s*\[([^\]\n]+)\]\s*(.+?)\s*$/;

function labelledLines(description) {
  return String(description ?? "").split("\n")
    .map(l => l.match(LABEL_LINE))
    .filter(Boolean)
    .map(m => ({ label: m[1].trim(), text: m[2] }));
}

// Each labelled line, looked up word for word in the confirmation list. A line that is not there is
//   still a condition: it is passed on unconfirmed and verifyProviderCondition reports it unverified,
//   so the skeleton routes it by its label ([Required] → definition_repair, [Verify] → ask_user).
//   BREAKS: drop an unconfirmed line here and a provider who rewords a condition silently removes it.
function providerConditionsFrom(mcpTool, confirmed) {
  const entries = confirmed?.tools?.[mcpTool?.name] ?? [];
  return labelledLines(mcpTool?.description).map((line, i) => {
    const hit = entries.find(e => typeof e?.label === "string" &&
      e.label.toLowerCase() === line.label.toLowerCase() && e.stated_as === line.text);
    if (hit) {
      // Fields the gate does not use (a version, a confirmation date, who confirmed) travel with the
      //   condition into the record, so a record says which confirmed wording it was judged under (6.1).
      const { label: _l, stated_as: _s, ...carried } = hit;
      return { ...carried, id: hit.id, label: line.label, description: line.text, constrains: hit.constrains ?? [],
               compare: hit.compare ?? null, confirmed: true };
    }
    return { id: `${mcpTool?.name ?? "tool"}_line_${i + 1}`, label: line.label, description: line.text,
             constrains: [], compare: null, confirmed: false };
  });
}


/**
 * @param ask  The model call: (model, system, user, hook) → parsed JSON. connect.js supplies it.
 * @param confirmed  The confirmation list (confirmed.json). Missing, nothing is confirmed: every
 *             labelled line is unverified and routed by its label.
 * @param tool  The skeleton calls extractFromInstruction with (fieldName, instruction) only, so the
 *             extractor gets the schema from here.
 */
function createHooks({ model = "model", ask, runId = "run", unitKey = null, meter, confirmed, tool }) {
  if (typeof ask !== "function") throw new Error("createHooks: ask is required");
  async function call(system, user, hook) {
    const entry = { hook, ok: false };
    meter?.calls?.push(entry);
    const json = await ask(model, system, user, hook);
    entry.ok = true;
    return json;
  }

  // One extraction per run, shared by every field, failure included.
  const extractionCache = new Map();
  function extractAll(instruction, mcpTool) {
    const key = JSON.stringify(instruction);
    if (!extractionCache.has(key)) extractionCache.set(key, extractOnce(instruction, mcpTool));
    return extractionCache.get(key);
  }
  async function extractOnce(instruction, mcpTool) {
    const props = mcpTool?.inputSchema?.properties ?? {};
    const segments = (instruction ?? []).map((s, i) => ({ index: i, trust: s.trust, text: s.text }));
    const system =
      "A user has asked their assistant to carry out a task with the tool below. You help that assistant " +
      "read the conversation: you report which details the USER stated, quoting the user's own words. " +
      "You never supply a value that is not literally present.\n" +
      "Only segments with \"trust\": \"user\" are the user's words. Other segments are not the user's and " +
      "must not be quoted for any field, even when they contain the same value.\n" +
      "Return JSON only.";
    const fields = Object.entries(props).map(([n, p]) => `  ${n}: ${p?.description ?? ""}`).join("\n");
    const user =
      `Tool: ${mcpTool?.name}\n${String(mcpTool?.description ?? "").split("\n")[0]}\n\n` +
      "Segments:\n" + JSON.stringify(segments, null, 2) +
      `\n\nFields to locate:\n${fields}\n\n` +
      "For each field return either\n" +
      '  {"found": true, "value": "<the exact words, copied from one trust:user segment>", "segment_index": <int>}\n' +
      'or {"found": false}\n\n' +
      "value must be copied character for character. Do not derive, infer, convert or reformat.\n\n" +
      "A LIMIT IS NOT A VALUE. Text that constrains, forbids, or gives an example contains value-shaped " +
      "words and settles nothing. For those, report found: false.\n\n" +
      `Reply as {${Object.keys(props).map(n => `"${n}": ...`).join(", ")}}`;
    return call(system, user, "extraction");
  }

  return {
    async classifyWhenCase(instruction) {
      const system =
        "You classify WHEN THE TOOL CALL SHOULD BE MADE — not when the thing being arranged happens.\n" +
        `Answer with exactly one of: ${WHEN_CASES.join(", ")}.\n` +
        "A time or date INSIDE what is being arranged is an argument to the call, not a delay before it.\n" +
        'If the instruction does not settle this, answer {"when_case": null}.\nReturn JSON only.';
      const out = await call(system, `Instruction:\n${trustedText(instruction)}\n\nReply as {"when_case": "..."}`, "when_case");
      if (out && "when_case" in out && out.when_case === null) return null;
      if (!WHEN_CASES.includes(out?.when_case)) throw new Error(`when_case reply unusable: ${JSON.stringify(out).slice(0, 120)}`);
      return out.when_case;
    },

    // A located claim; the gate checks it (spec 4.1).
    async extractUserActionName(instruction) {
      const segments = (instruction ?? []).map((s, i) => ({ index: i, trust: s?.trust, text: s?.text }))
        .filter(s => s.trust === "user");
      const out = await call(
        "You report what the speaker calls the action they are asking for, quoting their own words exactly. " +
        "Do not paraphrase or use tool names. Return JSON only.",
        "Segments:\n" + JSON.stringify(segments, null, 2) +
        '\n\nReply as {"action_name": "<exact words>", "segment_index": <int>} or {"action_name": null}.', "action_name");
      if (out && "action_name" in out && out.action_name === null) return { none: "absent" };
      const quote = typeof out?.action_name === "string" ? out.action_name.trim() : "";
      if (!quote || quote.length > 60) throw new Error("action name unusable");
      const idx = out?.segment_index;
      const text = Number.isInteger(idx) ? (instruction ?? [])[idx]?.text : undefined;
      return { value: quote, segment_index: idx ?? null, span: locateQuote(text, quote) };
    },

    // DISCLOSED: one tool, nothing to choose between. Spec 8.1: tool selection is not proven in code.
    confirmToolNameMatchesIntent(userActionName, mcpTool) {
      return { approved: true, reason: `single-tool example: '${userActionName}' accepted for '${mcpTool?.name}' without comparison` };
    },

    // Returns a location and the words at it, never a value of its own. Words that are not in the
    //   slot's declared form ("2pm this Saturday" for a date-time) fail validateFieldSchema and are
    //   asked about.
    async extractFromInstruction(fieldName, instruction) {
      let all;
      try { all = await extractAll(instruction, tool); }
      catch (e) { throw new Error(`extraction failed: ${e.message}`); }
      const hit = all?.[fieldName];
      if (hit?.found === false) return { none: "absent" };
      if (!hit || hit.found !== true) return undefined;
      const { value, segment_index } = hit;
      const seg = (instruction ?? [])[segment_index];
      return { value, segment_index, span: locateQuote(seg?.text, value) };
    },

    // Equality of the words at the span and the value. Words inside a limit the user declared never
    //   reach this hook: the skeleton refuses them first ([LIMIT WORDING]).
    spanSupportsValue(value, textAtSpan) {
      return squash(value) === squash(textAtSpan);
    },

    // The field's own schema, as the provider declared it, checked by the validator. A schema it
    //   cannot compile is a check not made: unverified, which the skeleton sends to definition repair.
    validateFieldSchema(value, schema, ctx, fieldName) {
      if (!schema) return null;
      const out = checkAgainst(schema, value);
      if (out.error) return { unverified: `"${fieldName}" has a schema the validator cannot run: ${out.error}` };
      return out.ok ? null : `"${fieldName}" does not match its declared schema: ${out.errors}; got ${JSON.stringify(value)}`;
    },

    // The whole argument object against the tool's input schema, by the same validator.
    validatePayload(args, inputSchema) {
      if (!inputSchema) return null;
      const out = checkAgainst(inputSchema, args);
      if (out.error) return { unverified: `the input schema cannot be run by the validator: ${out.error}` };
      return out.ok ? null : `the arguments do not match the input schema: ${out.errors}`;
    },

    measureFromEnvironment(fieldName, ctx) {
      const src = ctx?.measured_data;
      return (src && fieldName in src) ? src[fieldName] : undefined;
    },

    getAllowedSources(fieldName, mcpTool) {
      const declared = mcpTool?.inputSchema?.properties?.[fieldName]?.["x-allowed-sources"];
      return Array.isArray(declared) ? declared : null;
    },

    getProviderConditions(mcpTool) {
      return providerConditionsFrom(mcpTool, confirmed);
    },

    verifyProviderCondition(cond, ctx) {
      if (cond?.confirmed !== true) {
        return { status: "unverified", source: null, note: "this line is not in the confirmation list, word for word" };
      }
      const c = cond.compare;
      if (c?.source !== "measured_data" || typeof c.measure !== "string") {
        return { status: "unverified", source: null, note: "the confirmed form names no measurement to check" };
      }
      const m = ctx?.measured_data?.[c.measure];
      if (m?.valid !== true) return { status: "unverified", source: null, note: `no measurement of ${c.measure}` };
      const out = checkAgainst(c.schema, m.value);
      if (out.error) return { status: "unverified", source: null, note: `the confirmed schema cannot be run: ${out.error}` };
      return out.ok
        ? { status: "checked", source: "measured_data", note: `${c.measure} = ${JSON.stringify(m.value)}` }
        : { status: "unmet", source: "measured_data", note: `${c.measure} = ${JSON.stringify(m.value)}: ${out.errors}` };
    },

    verifyUserChecklistItem(item, ctx) {
      // An item with no comparison form is the seller's to confirm. A yes or a no the seller gave to
      //   this item (checklistAnswers, keyed by its id) settles it, with the seller as the source. It
      //   never overrides a comparison form: where code can compare, the seller's yes is not asked for.
      const answered = ctx?.checklistAnswers?.[item?.id];
      if (!item?.compare && (answered === true || answered === false)) {
        return { ...item, status: answered ? "verified" : "unmet", source: "user_answer",
                 note: answered ? "the seller confirmed it" : "the seller said it does not hold" };
      }
      const slot = Array.isArray(item?.constrains) ? item.constrains[0] : undefined;
      if (!item?.compare || !slot) {
        return { ...item, status: "unverified", source: null, note: "no confirmed comparison form" };
      }
      const field = (ctx?.fields ?? []).find(f => f.name === slot);
      const out = checkAgainst(item.compare, field?.value);
      if (out.error) {
        return { ...item, status: "unverified", source: null, note: `the confirmed schema cannot be run: ${out.error}` };
      }
      return out.ok
        ? { ...item, status: "verified", source: field?.source ?? null, note: `${slot}=${JSON.stringify(field.value)} satisfies the confirmed schema` }
        : { ...item, status: "unmet", source: field?.source ?? null, note: `${slot}=${JSON.stringify(field?.value)}: ${out.errors}` };
    },

    // The unit's key, the same in every round of one conversation (the graph's thread). The skeleton
    //   reads this unit's records under it: what was asked, and how often (spec 4.5, 4.6). A key unique
    //   per round would show it a unit that was never asked anything, and refuse every answer.
    buildActionKey(userId, fixed) {
      return `${userId}:${fixed?.c3_provider_action_name ?? "unknown"}:${unitKey ?? runId}`;
    },
  };
}

// Append-only, and load returns only the most recent executed record (spec 5.2).
function createStorage() {
  const m = new Map();
  return {
    async persist(key, record) {
      const k = key ?? "UNKEYED";
      m.set(k, [...(m.get(k) ?? []), record]);
      return record;
    },
    async load(key) {
      const arr = m.get(key) ?? [];
      for (let i = arr.length - 1; i >= 0; i--) if (arr[i]?.execution_decision === "executed") return arr[i];
      return null;
    },
    // Every record under the key, oldest first. The gate reads confirmed forms this way.
    async list(key) {
      return [...(m.get(key) ?? [])];
    },
  };
}

const last = (a, b) => (b === undefined ? a : b);
const merge = (a, b) => ({ ...(a ?? {}), ...(b ?? {}) });

const State = Annotation.Root({
  // Fixed for the run: the user turn, what the platform measured, the seller's checklist.
  segments: Annotation({ reducer: last, default: () => [] }),
  measuredData: Annotation({ reducer: last, default: () => ({}) }),
  userChecklist: Annotation({ reducer: last, default: () => [] }),
  // Values a model proposed for the seller to confirm. Shown as defaults; they settle nothing.
  proposals: Annotation({ reducer: last, default: () => ({}) }),
  // What the seller submitted, accumulated across asks.
  userAnswers: Annotation({ reducer: merge, default: () => ({}) }),
  checklistAnswers: Annotation({ reducer: merge, default: () => ({}) }),
  asks: Annotation({ reducer: last, default: () => 0 }),
  verdict: Annotation({ reducer: last, default: () => null }),
  ended: Annotation({ reducer: last, default: () => null }),
  executedWith: Annotation({ reducer: last, default: () => null }),
  serverRequests: Annotation({ reducer: last, default: () => null }),
  callError: Annotation({ reducer: last, default: () => null }),
});

const CHECK_PREFIX = "confirm__";

// The question for what the gate listed, in the shape of an MCP elicitation request (mode, message,
//   requestedSchema). It is not sent over MCP: in MCP a server asks, and here the gate asks, before
//   any call. The shape is borrowed so a client that renders elicitation forms can render this one.
//   Field schemas are the tool's own, without its x- keywords (an elicitation form takes a flat
//   object of primitive fields). An item the seller must confirm
//   becomes a yes/no field.
function elicitationFor(verdict, tool, proposals) {
  const props = {};
  for (const name of verdict.askFields) {
    const p = tool.inputSchema?.properties?.[name] ?? { type: "string" };
    props[name] = {
      type: p.type ?? "string",
      ...(p.format ? { format: p.format } : {}),
      ...(p.description ? { description: p.description } : {}),
      ...(Array.isArray(p.enum) ? { enum: p.enum } : {}),
      ...(proposals?.[name] !== undefined ? { default: proposals[name] } : {}),
    };
  }
  for (const item of verdict.askItems) {
    props[CHECK_PREFIX + item.id] = { type: "boolean", title: item.id, description: `Does this hold: "${item.description}"?` };
  }
  return {
    mode: "form",
    message: `Before ${tool.name} can run, please provide: ${Object.keys(props).join(", ")}`,
    requestedSchema: { type: "object", properties: props, required: Object.keys(props) },
  };
}

// The elicitation reply as JSON Schema: an action, and content in the shape the request asked for.
function replySchemaFor(request) {
  return {
    type: "object",
    properties: {
      action: { type: "string", enum: ["accept", "decline", "cancel"] },
      content: request.requestedSchema,
    },
    required: ["action"],
  };
}

// Keeps only what was asked for, of the type asked for. A key the request did not name is dropped, so
//   a reply cannot add an argument the gate did not ask the seller for. The format is not checked here:
//   the gate checks it, and asks again if it fails.
function acceptContent(request, content, askItems = []) {
  const answers = {}, checklist = {};
  for (const [key, schema] of Object.entries(request.requestedSchema.properties)) {
    if (!content || !(key in content)) continue;
    const v = content[key];
    if (schema.type === "boolean") {
      if (typeof v === "boolean") {
        // The answer is bound to what the question showed: the item's version and its values (6.3).
        const id = key.slice(CHECK_PREFIX.length);
        const shown = askItems.find(i => i.id === id)?.approve;
        if (shown) checklist[id] = { answer: v, shown: shown.shown ?? {}, rule_hash: shown.rule_hash ?? null };
      }
    } else if (typeof v === "string" && v.trim() !== "") {
      answers[key] = v;
    }
  }
  return { answers, checklist };
}

/**
 * @param ask, callTool, checkpointer, storage   from connect.js
 * @param tool, confirmed                         tool.json, confirmed.json
 * storage defaults to an in-memory store and checkpointer to MemorySaver. Both are for trying the
 *   example. A real system passes its own: the record append-only, where the agent cannot rewrite it
 *   (spec 8.2), and a checkpointer that survives a restart.
 */
function buildGraph({ ask, callTool, tool, confirmed, checkpointer = new MemorySaver(), storage = createStorage(), userId = "user", runId = "graph" }) {
  if (!tool) throw new Error("buildGraph: tool is required");
  let round = 0;

  async function gate(state, config) {
    round += 1;
    const unitKey = config?.configurable?.thread_id ?? runId;
    const hooks = createHooks({ ask, runId: `${runId}-${round}`, unitKey, tool, confirmed });
    const preflight = createPreflight({ hooks, storage });
    const st = await preflight.runPreflight({
      userId, instruction: state.segments, mcpTool: tool, preSetData: {},
      measured_data: state.measuredData, userChecklist: state.userChecklist,
      userAnswers: state.userAnswers, checklistAnswers: state.checklistAnswers,
      intent_attempt: 0, tool_attempt: 0, ask_attempt: state.asks,
    });
    await preflight.recordExecutionState(st);
    return { verdict: {
      decision: st.execution_decision,
      reason: st.reason,
      call_arguments: st.execution_decision === "execute" ? st.call_arguments : null,
      // The blanks on the ask route, from the gate's own field records — not re-derived here.
      askFields: (st.fields ?? []).filter(f => f.status === "unknown" && f.route === "ask_user").map(f => f.name),
      // Every approval the gate asks for — the seller's own conditions and the provider's [Verify] lines —
      //   with what it shows (approve: the item's version and the values it is about). The answer goes
      //   back bound to exactly that (6.3); an item whose form is not confirmed yet is not asked here.
      askItems: [...(st.gate?.unverified_checklist ?? []), ...(st.gate?.unverified_provider ?? [])]
        .filter(i => i.approve)
        .map(i => ({ id: i.id, description: i.description, approve: i.approve })),
      fields: (st.fields ?? []).map(f => ({ name: f.name, status: f.status, source: f.source ?? null, route: f.route ?? null })),
      user_checklist: (st.user_checklist ?? []).map(i => ({ id: i.id, status: i.status, source: i.source ?? null })),
    } };
  }

  function askNode(state) {
    // Runs again from the top on resume (LangGraph re-executes the node), so everything before
    //   interrupt() is a pure function of the state.
    const request = elicitationFor(state.verdict, tool, state.proposals);
    // The reply's shape also goes in LangGraph's own slot for it (responseSchema), so a client finds the
    //   form at Interrupt.response_schema. A JSON Schema there is passed through, not enforced: whether
    //   the answer counts stays with the gate, so a failed answer is recorded and counted toward the
    //   ceiling instead of ending the run as a validation error.
    const reply = interrupt(request, { responseSchema: replySchemaFor(request) });
    if (reply?.action !== "accept") return { ended: reply?.action === "decline" ? "declined" : "cancelled" };
    const { answers, checklist } = acceptContent(request, reply.content, state.verdict.askItems);
    return { userAnswers: answers, checklistAnswers: checklist, asks: state.asks + 1 };
  }

  // The server may answer with a request for more input instead of completing (MCP 2026-07-28,
  //   input_required). That input would not pass the gate, so the run stops: not executed, with the
  //   server's request kept for the caller to see.
  async function execute(state) {
    const args = state.verdict.call_arguments;
    let result;
    // A call that fails is reported, not retried: whether the tool did anything is for the caller to
    //   find out from the tool's side.
    try { result = await callTool(tool.name, args); }
    catch (e) { return { ended: "call_failed", callError: String(e?.message ?? e) }; }
    if (result && typeof result === "object" && result.inputRequired) {
      return { ended: "input_required", serverRequests: result.inputRequired };
    }
    // The tool ran and reported a failure (MCP's isError). Not "executed": what was asked did not happen.
    if (result && typeof result === "object" && result.isError === true) {
      const text = (result.content ?? []).map(c => c?.text ?? "").join(" ").trim();
      return { ended: "tool_error", callError: text || "the tool reported an error" };
    }
    return { ended: "executed", executedWith: args };
  }

  return new StateGraph(State)
    .addNode("gate", gate)
    .addNode("ask", askNode)
    .addNode("execute", execute)
    .addEdge(START, "gate")
    .addConditionalEdges("gate", s => {
      if (s.verdict.decision === "execute") return "execute";
      if (s.verdict.decision === "ask_user" && (s.verdict.askFields.length + s.verdict.askItems.length) > 0) return "ask";
      return END;
    }, ["execute", "ask", END])
    .addConditionalEdges("ask", s => (s.ended ? END : "gate"), ["gate", END])
    .addEdge("execute", END)
    .compile({ checkpointer });
}

// The measurements the declarations name: every slot whose schema allows measured_data (directly or
//   as a value settled at execution), and every measurement a confirmed form reads. agent.js asks
//   connect.measure for exactly these, so what is measured is decided by what is declared.
function measurementsNeeded(tool, confirmed) {
  const names = new Set();
  for (const [name, p] of Object.entries(tool?.inputSchema?.properties ?? {})) {
    const allowed = p?.["x-allowed-sources"];
    if (p?.["x-settled-at-execution"] === true || (Array.isArray(allowed) && allowed.includes("measured_data"))) names.add(name);
  }
  for (const entry of confirmed?.tools?.[tool?.name] ?? []) {
    if (entry?.compare?.source === "measured_data" && typeof entry.compare.measure === "string") names.add(entry.compare.measure);
  }
  return [...names];
}

module.exports = {
  createHooks, createStorage, buildGraph, measurementsNeeded,
  labelledLines, providerConditionsFrom, checkAgainst, elicitationFor, replySchemaFor, acceptContent,
  State, CHECK_PREFIX, WHEN_CASES, Command, MemorySaver,
};
